CREATE OR REPLACE FUNCTION public.npc_media_ticket_v1(p_template uuid, p_narrative_version uuid, p_kind text, p_request uuid, p_sha256 text, p_bytes bigint, p_mime text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_admin boolean; t public.nb_templates%rowtype;
        v public.nb_template_versions%rowtype;
        h png_builder_internal.npc_combat_draft_heads%rowtype;
        old png_builder_internal.npc_media_tickets%rowtype;
        latest uuid; ext text; v_path text; v_asset_id text;
begin
  if v_uid is null or not public.is_staff() then raise exception 'NPC_MEDIA_AUTH' using errcode='42501'; end if;
  if p_template is null or p_narrative_version is null or p_request is null or
     coalesce(p_kind,'') not in ('portrait','marker') or coalesce(p_sha256,'') !~ '^[0-9a-f]{64}$' or
     coalesce(p_bytes,0) not between 1 and 4194304 or
     coalesce(p_mime,'') not in ('image/png','image/jpeg','image/webp')
    then raise exception 'NPC_MEDIA_INPUT' using errcode='22023'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_request::text,25092025));
  select p.role='admin' into v_admin from public.profiles p where p.id=v_uid;
  select * into t from public.nb_templates where id=p_template for update;
  if not found or t.deactivated_at is not null or
     (t.created_by is distinct from v_uid and not coalesce(v_admin,false))
    then raise exception 'NPC_MEDIA_AUTH' using errcode='42501'; end if;
  select * into old from png_builder_internal.npc_media_tickets where request_key=p_request;
  if found then
    if old.actor_id is distinct from v_uid or old.template_id is distinct from p_template or
       old.narrative_version_id is distinct from p_narrative_version or
       old.kind is distinct from p_kind or old.sha256 is distinct from p_sha256 or
       old.bytes is distinct from p_bytes or old.mime_type is distinct from p_mime
      then raise exception 'NPC_MEDIA_REQUEST_MISMATCH' using errcode='22023'; end if;
    select * into v from public.nb_template_versions
      where id=p_narrative_version and template_id=p_template;
    select x.id into latest from public.nb_template_versions x
      where x.template_id=p_template and x.review_state='draft'
      order by x.version_no desc limit 1;
    if v.id is null or v.content_sha256 is distinct from old.narrative_content_sha256 or
       v.mechanical_template_id is distinct from old.mechanical_template_id or
       (latest is not null and latest is distinct from p_narrative_version) or
       (v.review_state='approved' and t.current_version_id is distinct from p_narrative_version) or
       (old.state='pending' and v.review_state<>'draft')
      then raise exception 'NPC_MEDIA_STALE' using errcode='55000'; end if;
    return png_builder_internal.npc_media_ticket_view_v1(old);
  end if;
  select * into v from public.nb_template_versions
    where id=p_narrative_version and template_id=p_template for update;
  select * into h from png_builder_internal.npc_combat_draft_heads
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version for share;
  select x.id into latest from public.nb_template_versions x
    where x.template_id=p_template and x.review_state='draft'
    order by x.version_no desc limit 1;
  if v.id is null or v.review_state<>'draft' or latest is distinct from p_narrative_version or
     (v.mechanical_template_id is null and h.narrative_template_id is not null and
       (h.combat is distinct from false or h.mechanical_template_id is not null or
        h.review_state<>'draft')) or
     (v.mechanical_template_id is not null and
       (h.narrative_template_id is null or h.combat is distinct from true or
        h.review_state<>'draft' or
        v.mechanical_template_id is distinct from h.mechanical_template_id))
    then raise exception 'NPC_MEDIA_STALE' using errcode='55000'; end if;
  ext:=case p_mime when 'image/png' then 'png' when 'image/jpeg' then 'jpg' else 'webp' end;
  -- Preserve the live NBE media object_path CHECK and asset_id CHECK.
  -- Request and full byte hash make the path unique without an upsert.
  v_asset_id:='npc_'||p_kind||'_'||replace(p_request::text,'-','')||'_'||p_sha256;
  v_path:='ninja-book/'||t.template_key||'/r'||v.version_no::text||
    '/assets/'||v_asset_id||'_v1.'||ext;
  insert into png_builder_internal.npc_media_tickets(
    request_key,actor_id,template_id,narrative_version_id,kind,asset_id,object_path,
    sha256,bytes,mime_type,narrative_content_sha256,mechanical_template_id)
  values(p_request,v_uid,p_template,p_narrative_version,p_kind,v_asset_id,v_path,
    p_sha256,p_bytes,p_mime,v.content_sha256,v.mechanical_template_id)
  returning * into old;
  return png_builder_internal.npc_media_ticket_view_v1(old);
end $function$

CREATE OR REPLACE FUNCTION public.npc_media_register_v1(p_request uuid, p_sha256 text, p_bytes bigint, p_mime text, p_width integer, p_height integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  x png_builder_internal.npc_media_tickets%rowtype;
  t public.nb_templates%rowtype;
  v public.nb_template_versions%rowtype;
  h png_builder_internal.npc_combat_draft_heads%rowtype;
  latest uuid;
  obj_mime text;
  obj_bytes bigint;
  receipt jsonb;
begin
  if coalesce(auth.jwt()->>'role','')<>'service_role' then
    raise exception 'NPC_MEDIA_SERVICE_REQUIRED' using errcode='42501';
  end if;
  if p_request is null or coalesce(p_sha256,'') !~ '^[0-9a-f]{64}$' or
     coalesce(p_bytes,0) not between 1 and 4194304 or
     coalesce(p_mime,'') not in ('image/png','image/jpeg','image/webp') or
     coalesce(p_width,0) not between 1 and 8192 or
     coalesce(p_height,0) not between 1 and 8192 then
    raise exception 'NPC_MEDIA_INPUT' using errcode='22023';
  end if;

  select * into x from png_builder_internal.npc_media_tickets
    where request_key=p_request for update;
  if not found then raise exception 'NPC_MEDIA_TICKET_MISSING' using errcode='55000'; end if;
  if x.sha256 is distinct from p_sha256 or x.bytes is distinct from p_bytes or
     x.mime_type is distinct from p_mime then
    raise exception 'NPC_MEDIA_REQUEST_MISMATCH' using errcode='22023';
  end if;
  if x.state='registered' or x.state='approved' then
    if x.width_px is distinct from p_width or x.height_px is distinct from p_height or
       x.registration is null then
      raise exception 'NPC_MEDIA_REQUEST_MISMATCH' using errcode='22023';
    end if;
    return x.registration;
  end if;
  if x.state<>'pending' or x.expires_at<=clock_timestamp() then
    raise exception 'NPC_MEDIA_EXPIRED' using errcode='55000';
  end if;

  select * into t from public.nb_templates where id=x.template_id for update;
  select * into v from public.nb_template_versions
    where id=x.narrative_version_id and template_id=x.template_id for update;
  select * into h from png_builder_internal.npc_combat_draft_heads
    where narrative_template_id=x.template_id and narrative_version_id=x.narrative_version_id
    for share;
  select q.id into latest from public.nb_template_versions q
    where q.template_id=x.template_id and q.review_state='draft'
    order by q.version_no desc limit 1;
  if t.id is null or t.deactivated_at is not null or
     v.id is null or v.review_state<>'draft' or
     latest is distinct from x.narrative_version_id or
     h.narrative_template_id is null or h.review_state<>'draft' or
     v.content_sha256 is distinct from x.narrative_content_sha256 or
     v.mechanical_template_id is distinct from x.mechanical_template_id or
     h.mechanical_template_id is distinct from x.mechanical_template_id then
    raise exception 'NPC_MEDIA_STALE' using errcode='55000';
  end if;

  select o.metadata->>'mimetype',(o.metadata->>'size')::bigint
    into obj_mime,obj_bytes from storage.objects o
    where o.bucket_id=x.bucket and o.name=x.object_path;
  if not found or obj_mime is distinct from x.mime_type or
     obj_bytes is distinct from x.bytes then
    raise exception 'NPC_MEDIA_STORAGE_DRIFT' using errcode='55000';
  end if;

  receipt:=pg_catalog.jsonb_build_object(
    'schema_version','npc-media-registration/1',
    'request_key',x.request_key,'template_id',x.template_id,
    'narrative_version_id',x.narrative_version_id,'kind',x.kind,
    'media_id',x.media_id,'asset_id',x.asset_id,
    'bucket',x.bucket,'object_path',x.object_path,
    'sha256',x.sha256,'bytes',x.bytes,'mime_type',x.mime_type,
    'width_px',p_width,'height_px',p_height,
    'narrative_content_sha256',x.narrative_content_sha256,
    'mechanical_template_id',x.mechanical_template_id,
    'state','registered');
  update png_builder_internal.npc_media_tickets
    set state='registered',width_px=p_width,height_px=p_height,
        registration=receipt,registered_at=clock_timestamp()
    where request_key=x.request_key;
  return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.npc_media_approve_pair_v1(p_template uuid, p_narrative_version uuid, p_portrait_request uuid, p_marker_request uuid, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid:=auth.uid();
  t public.nb_templates%rowtype;
  v public.nb_template_versions%rowtype;
  h png_builder_internal.npc_combat_draft_heads%rowtype;
  portrait png_builder_internal.npc_media_tickets%rowtype;
  marker png_builder_internal.npc_media_tickets%rowtype;
  prior png_builder_internal.npc_media_pairs%rowtype;
  old_media public.nb_template_media_versions%rowtype;
  old_marker png_builder_internal.npc_marker_versions%rowtype;
  media_no integer;
  marker_no integer;
  fp text;
  mime_check text;
  bytes_check bigint;
  approved jsonb;
  receipt jsonb;
begin
  if actor is null or not public.is_staff() or not exists(
    select 1 from public.profiles p where p.id=actor and p.role='admin') then
    raise exception 'NPC_MEDIA_ADMIN_REQUIRED' using errcode='42501';
  end if;
  if p_template is null or p_narrative_version is null or p_portrait_request is null or
     p_marker_request is null or p_request_key is null or
     p_portrait_request=p_marker_request then
    raise exception 'NPC_MEDIA_INPUT' using errcode='22023';
  end if;
  fp:=ninja_book_internal.json_hash(pg_catalog.jsonb_build_object(
    'template',p_template,'version',p_narrative_version,
    'portrait',p_portrait_request,'marker',p_marker_request));
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('npc-media-pair:'||p_request_key::text,25092025));
  select * into prior from png_builder_internal.npc_media_pairs
    where request_key=p_request_key;
  if found then
    if prior.fingerprint is distinct from fp then
      raise exception 'NPC_MEDIA_REQUEST_MISMATCH' using errcode='22023';
    end if;
    return prior.response || pg_catalog.jsonb_build_object('replayed',true);
  end if;

  select * into t from public.nb_templates where id=p_template for update;
  select * into v from public.nb_template_versions
    where id=p_narrative_version and template_id=p_template for update;
  select * into h from png_builder_internal.npc_combat_draft_heads
    where narrative_template_id=p_template and narrative_version_id=p_narrative_version
    for share;
  if t.id is null or t.deactivated_at is not null or
     t.lifecycle_state<>'approved' or t.current_version_id is distinct from p_narrative_version or
     v.id is null or v.review_state<>'approved' or
     (v.mechanical_template_id is null and h.narrative_template_id is not null and
       (h.combat is distinct from false or h.mechanical_template_id is not null or
        h.review_state<>'approved')) or
     (v.mechanical_template_id is not null and
       (h.narrative_template_id is null or h.combat is distinct from true or
        h.review_state<>'approved' or
        v.mechanical_template_id is distinct from h.mechanical_template_id)) then
    raise exception 'NPC_MEDIA_STALE' using errcode='55000';
  end if;
  perform 1 from png_builder_internal.npc_media_tickets x
    where x.request_key in (p_portrait_request,p_marker_request)
    order by x.request_key for update;
  select * into portrait from png_builder_internal.npc_media_tickets
    where request_key=p_portrait_request;
  select * into marker from png_builder_internal.npc_media_tickets
    where request_key=p_marker_request;
  if portrait.request_key is null or marker.request_key is null or
     portrait.kind<>'portrait' or marker.kind<>'marker' or
     portrait.state<>'registered' or marker.state<>'registered' or
     portrait.template_id is distinct from p_template or marker.template_id is distinct from p_template or
     portrait.narrative_version_id is distinct from p_narrative_version or
     marker.narrative_version_id is distinct from p_narrative_version or
     portrait.narrative_content_sha256 is distinct from v.content_sha256 or
     marker.narrative_content_sha256 is distinct from v.content_sha256 or
     portrait.mechanical_template_id is distinct from v.mechanical_template_id or
     marker.mechanical_template_id is distinct from v.mechanical_template_id then
    raise exception 'NPC_MEDIA_STALE' using errcode='55000';
  end if;
  if exists(select 1 from png_builder_internal.npc_media_pairs q
      where q.narrative_version_id=p_narrative_version and q.state='approved') then
    raise exception 'NPC_MEDIA_PAIR_EXISTS' using errcode='55000';
  end if;
  select o.metadata->>'mimetype',(o.metadata->>'size')::bigint
    into mime_check,bytes_check from storage.objects o
    where o.bucket_id=portrait.bucket and o.name=portrait.object_path;
  if not found or mime_check is distinct from portrait.mime_type or
     bytes_check is distinct from portrait.bytes then
    raise exception 'NPC_MEDIA_STORAGE_DRIFT' using errcode='55000';
  end if;
  select o.metadata->>'mimetype',(o.metadata->>'size')::bigint
    into mime_check,bytes_check from storage.objects o
    where o.bucket_id=marker.bucket and o.name=marker.object_path;
  if not found or mime_check is distinct from marker.mime_type or
     bytes_check is distinct from marker.bytes then
    raise exception 'NPC_MEDIA_STORAGE_DRIFT' using errcode='55000';
  end if;

  select * into old_media from public.nb_template_media_versions
    where template_id=p_template and active for update;
  select coalesce(max(q.media_version_no),0)+1 into media_no
    from public.nb_template_media_versions q where q.template_id=p_template;
  if old_media.id is null and media_no>1 then
    select * into old_media from public.nb_template_media_versions q
      where q.template_id=p_template and q.media_version_no=media_no-1 and
        q.lifecycle_state='inactive' and q.approved_at is not null and
        q.superseded_by_media_id is null for update;
    if old_media.id is null then
      raise exception 'NPC_MEDIA_SUPERSESSION_REQUIRED' using errcode='55000';
    end if;
  end if;
  insert into public.nb_template_media_versions(
    id,template_id,template_version_id,media_version_no,supersedes_media_id,
    schema_version,asset_id,asset_version,kind,bucket,object_path,
    sha256,verified_sha256,mime_type,width_px,height_px,bytes,alt_text,
    provenance,lifecycle_state,active,created_by,reviewed_by,reviewed_at)
  values(
    portrait.media_id,p_template,p_narrative_version,media_no,old_media.id,
    'ninja-book-media/1.1',portrait.asset_id,1,'canonical_full_body',
    portrait.bucket,portrait.object_path,portrait.sha256,portrait.sha256,
    portrait.mime_type,portrait.width_px,portrait.height_px,portrait.bytes,
    'Ritratto a figura intera di '||t.display_name,
    pg_catalog.jsonb_build_object(
      'source_task','MISSION-FACTORY-PNG-MEDIA-PAIR-20260925',
      'provider',pg_catalog.jsonb_build_object('name','staff_upload'),
      'generated_at',portrait.registered_at,
      'verification',pg_catalog.jsonb_build_object(
        'method','edge_byte_sha256','request_key',portrait.request_key,
        'verified_sha256',portrait.sha256)),
    'review',false,portrait.actor_id,actor,clock_timestamp());
  approved:=public.nb_admin_media_approve(
    portrait.media_id,p_narrative_version,1,
    extensions.uuid_generate_v5(p_request_key,'npc-media-portrait-approve/1'));
  if approved->>'state' is distinct from 'approved' or
     (approved->>'media_id')::uuid is distinct from portrait.media_id then
    raise exception 'NPC_MEDIA_APPROVAL_FAILED' using errcode='55000';
  end if;

  select * into old_marker from png_builder_internal.npc_marker_versions
    where template_id=p_template and active for update;
  select coalesce(max(q.marker_version_no),0)+1 into marker_no
    from png_builder_internal.npc_marker_versions q where q.template_id=p_template;
  -- Insert inactive first: the prior marker can then point to this existing row.
  insert into png_builder_internal.npc_marker_versions(
    id,template_id,narrative_version_id,marker_version_no,supersedes_marker_id,
    asset_id,bucket,object_path,sha256,mime_type,bytes,width_px,height_px,
    active,state,created_by,approved_by)
  values(marker.media_id,p_template,p_narrative_version,marker_no,old_marker.id,
    marker.asset_id,marker.bucket,marker.object_path,marker.sha256,
    marker.mime_type,marker.bytes,marker.width_px,marker.height_px,
    false,'inactive',marker.actor_id,actor);
  if old_marker.id is not null then
    update png_builder_internal.npc_marker_versions
      set active=false,state='superseded',superseded_by_marker_id=marker.media_id
      where id=old_marker.id;
  end if;
  update png_builder_internal.npc_marker_versions
    set active=true,state='approved' where id=marker.media_id;

  receipt:=pg_catalog.jsonb_build_object(
    'schema_version','npc-media-pair/1','request_key',p_request_key,
    'replayed',false,
    'template_id',p_template,'narrative_version_id',p_narrative_version,
    'portrait_media_id',portrait.media_id,'portrait_sha256',portrait.sha256,
    'marker_media_id',marker.media_id,'marker_sha256',marker.sha256,
    'narrative_content_sha256',v.content_sha256,
    'mechanical_template_id',v.mechanical_template_id,
    'state','approved','active',true);
  insert into png_builder_internal.npc_media_pairs(
    request_key,template_id,narrative_version_id,portrait_request,marker_request,
    narrative_content_sha256,mechanical_template_id,actor_id,fingerprint,response)
  values(p_request_key,p_template,p_narrative_version,p_portrait_request,p_marker_request,
    v.content_sha256,v.mechanical_template_id,actor,fp,receipt);
  update png_builder_internal.npc_media_tickets set state='approved',approved_at=clock_timestamp()
    where request_key in (p_portrait_request,p_marker_request);
  return receipt;
end $function$
